package `in`.artham.fundamentals.data

import kotlin.math.abs
import kotlin.math.sin
import kotlin.random.Random

/**
 * A small, entirely synthetic dataset so the app is usable the moment it is
 * installed. Every entity here is fictional and every figure is generated by
 * this file - nothing is copied from any data vendor, and nothing is presented
 * as a real company's financials. Companies are flagged `isDemo = true`, which
 * puts a permanent DEMO badge on every screen that shows them.
 */
object DemoData {

    data class Blueprint(
        val code: String,
        val name: String,
        val sector: String,
        val industry: String,
        val baseSales: Double,
        val growth: Double,
        val opm: Double,
        val roeTarget: Double,
        val debtToEquity: Double,
        val dividendPayout: Double,
        val about: String
    )

    private val blueprints = listOf(
        Blueprint("DEMOINF", "Demo Infotech Ltd", "Technology", "IT Services", 24000.0, 0.11, 0.24, 0.30, 0.05, 0.62,
            "Synthetic sample entity generated by Artham to demonstrate an asset-light services business."),
        Blueprint("DEMOFMC", "Demo Consumer Ltd", "Consumer", "FMCG", 14200.0, 0.09, 0.21, 0.26, 0.12, 0.55,
            "Synthetic sample entity generated by Artham to demonstrate a branded consumer business."),
        Blueprint("DEMOBANK", "Demo Bank Ltd", "Financials", "Private Bank", 38000.0, 0.14, 0.34, 0.15, 0.90, 0.12,
            "Synthetic sample entity generated by Artham to demonstrate a lending business."),
        Blueprint("DEMOPHAR", "Demo Pharma Ltd", "Healthcare", "Pharmaceuticals", 8600.0, 0.10, 0.23, 0.19, 0.20, 0.30,
            "Synthetic sample entity generated by Artham to demonstrate a regulated manufacturing business."),
        Blueprint("DEMOAUTO", "Demo Auto Ltd", "Automobile", "Auto Ancillary", 19500.0, 0.07, 0.14, 0.16, 0.45, 0.25,
            "Synthetic sample entity generated by Artham to demonstrate a capital-intensive manufacturer."),
        Blueprint("DEMOSTEL", "Demo Steel Ltd", "Commodities", "Steel", 41000.0, 0.05, 0.11, 0.11, 0.85, 0.15,
            "Synthetic sample entity generated by Artham to demonstrate a cyclical commodity business."),
        Blueprint("DEMOCEM", "Demo Cement Ltd", "Materials", "Cement", 12800.0, 0.08, 0.19, 0.13, 0.35, 0.20,
            "Synthetic sample entity generated by Artham to demonstrate a regional infrastructure supplier."),
        Blueprint("DEMOENER", "Demo Energy Ltd", "Energy", "Power", 22400.0, 0.06, 0.28, 0.12, 1.10, 0.40,
            "Synthetic sample entity generated by Artham to demonstrate a regulated utility."),
        Blueprint("DEMOCHEM", "Demo Chemicals Ltd", "Materials", "Specialty Chemicals", 6400.0, 0.16, 0.25, 0.22, 0.25, 0.18,
            "Synthetic sample entity generated by Artham to demonstrate a high-growth specialty manufacturer."),
        Blueprint("DEMORETA", "Demo Retail Ltd", "Consumer", "Retail", 31500.0, 0.13, 0.08, 0.20, 0.30, 0.10,
            "Synthetic sample entity generated by Artham to demonstrate a low-margin high-turnover retailer."),
        Blueprint("DEMOLOGI", "Demo Logistics Ltd", "Industrials", "Logistics", 5200.0, 0.12, 0.18, 0.17, 0.55, 0.22,
            "Synthetic sample entity generated by Artham to demonstrate an asset-heavy services business."),
        Blueprint("DEMOAGRO", "Demo Agro Ltd", "Materials", "Agro Chemicals", 3900.0, 0.04, 0.15, 0.09, 0.65, 0.28,
            "Synthetic sample entity generated by Artham to demonstrate a slow-growth seasonal business.")
    )

    fun load(dao: CompanyDao, importDao: ImportDao): Pair<Int, Int> {
        var annualRows = 0
        var quarterlyRows = 0
        for ((index, bp) in blueprints.withIndex()) {
            val companyId = dao.upsert(
                Company(
                    code = bp.code, name = bp.name, sector = bp.sector, industry = bp.industry,
                    about = bp.about, consolidated = true, isDemo = true
                )
            )
            val rnd = Random(index * 7919 + 13)
            val annual = ArrayList<AnnualFinancial>()
            val startYear = 2017
            var sales = bp.baseSales
            for (year in startYear..2025) {
                val wobble = 1.0 + 0.045 * sin((year - startYear) * 1.3 + index)
                val growth = bp.growth * wobble
                if (year > startYear) sales *= (1.0 + growth)
                val opm = (bp.opm * (1.0 + 0.06 * sin(year.toDouble() + index))).coerceIn(0.02, 0.55)
                val operatingProfit = sales * opm
                val depreciation = sales * (0.03 + 0.02 * abs(sin(index.toDouble())))
                val interest = sales * (0.006 + bp.debtToEquity * 0.010)
                val otherIncome = sales * 0.012
                val pbt = operatingProfit - depreciation - interest + otherIncome
                val taxRate = 0.25
                val netProfit = pbt * (1 - taxRate)
                val equityCapital = sales * 0.02
                val reserves = netProfit * 6.5 + sales * 0.08
                val borrowings = sales * bp.debtToEquity * 0.28
                val fixedAssets = sales * 0.42
                val cwip = sales * 0.03
                val investments = sales * 0.10
                val receivables = sales * 0.14
                val inventory = sales * 0.11
                val payables = sales * 0.09
                val otherAssets = sales * 0.06
                val totalAssets = fixedAssets + cwip + investments + receivables + inventory + otherAssets
                val otherLiabilities = (totalAssets - equityCapital - reserves - borrowings).coerceAtLeast(totalAssets * 0.08)
                val totalLiabilities = equityCapital + reserves + borrowings + otherLiabilities
                val eps = netProfit / (equityCapital / 10.0)
                val dividend = eps * bp.dividendPayout
                val cfo = netProfit * 1.08
                val cfi = -sales * 0.05
                val cff = sales * 0.01
                annual.add(
                    AnnualFinancial(
                        companyId = companyId, fyEnd = year, sales = sales, expenses = sales - operatingProfit,
                        operatingProfit = operatingProfit, opmPercent = opm * 100, otherIncome = otherIncome,
                        interest = interest, depreciation = depreciation, profitBeforeTax = pbt,
                        taxPercent = taxRate * 100, netProfit = netProfit, eps = eps, dividend = dividend,
                        equityCapital = equityCapital, reserves = reserves, borrowings = borrowings,
                        otherLiabilities = otherLiabilities, totalLiabilities = totalLiabilities,
                        fixedAssets = fixedAssets, cwip = cwip, investments = investments,
                        otherAssets = otherAssets, totalAssets = totalAssets, receivables = receivables,
                        inventory = inventory, payables = payables, cfo = cfo, cfi = cfi, cff = cff,
                        netCashFlow = cfo + cfi + cff
                    )
                )
            }
            dao.replaceAnnual(companyId, annual)
            annualRows += annual.size

            val quarterly = ArrayList<QuarterlyFinancial>()
            val lastAnnual = annual.last()
            for (q in 0 until 8) {
                val fyEnd = 2025 - (7 - q) / 4
                val quarter = ((7 - q) % 4) + 1
                val label = quarterLabel(fyEnd, quarter)
                val season = 1.0 + 0.03 * rnd.nextDouble()
                val qSales = lastAnnual.sales!! / 4.0 * season * (1.0 + 0.01 * q)
                val qOpm = (lastAnnual.opmPercent!! / 100.0) * (1.0 + 0.02 * (rnd.nextDouble() - 0.5))
                val qOp = qSales * qOpm
                val qDep = lastAnnual.depreciation!! / 4.0
                val qInt = lastAnnual.interest!! / 4.0
                val qOther = lastAnnual.otherIncome!! / 4.0
                val qPbt = qOp - qDep - qInt + qOther
                val qNet = qPbt * 0.75
                quarterly.add(
                    QuarterlyFinancial(
                        companyId = companyId, fyEnd = fyEnd, quarter = quarter, label = label,
                        sales = qSales, expenses = qSales - qOp, operatingProfit = qOp, opmPercent = qOpm * 100,
                        otherIncome = qOther, interest = qInt, depreciation = qDep, profitBeforeTax = qPbt,
                        taxPercent = 25.0, netProfit = qNet, eps = qNet / (lastAnnual.equityCapital!! / 10.0) * 4
                    )
                )
            }
            dao.replaceQuarterly(companyId, quarterly)
            quarterlyRows += quarterly.size

            val shareholding = ArrayList<ShareholdingRow>()
            val promoterBase = 40.0 + (index * 4 % 25)
            for (q in 0 until 8) {
                val drift = sin(q.toDouble()) * 1.2
                val promoters = (promoterBase + drift).coerceIn(0.0, 75.0)
                val fii = (12.0 + 3 * sin(q * 0.7 + index)).coerceIn(0.5, 30.0)
                val dii = (9.0 + 2.5 * sin(q * 0.9 + index * 2)).coerceIn(0.5, 25.0)
                val gov = 0.4
                val publicHolding = (100.0 - promoters - fii - dii - gov).coerceAtLeast(0.0)
                val fyEnd = 2025 - (7 - q) / 4
                val quarter = ((7 - q) % 4) + 1
                shareholding.add(
                    ShareholdingRow(
                        companyId = companyId, label = quarterLabel(fyEnd, quarter), sortKey = fyEnd * 4 + quarter,
                        promoters = promoters, fii = fii, dii = dii, government = gov, publicHolding = publicHolding
                    )
                )
            }
            dao.replaceShareholding(companyId, shareholding)

            val last = annual.last()
            val shares = last.equityCapital!! / 10.0
            val price = (last.netProfit!! * 18.0) / shares
            dao.upsertQuote(
                Quote(
                    companyId = companyId, price = price, changePercent = (rnd.nextDouble() - 0.5) * 3.0,
                    high52 = price * 1.28, low52 = price * 0.74,
                    marketCap = price * shares, updatedAt = System.currentTimeMillis(), source = "demo"
                )
            )
        }
        importDao.record("Built-in demo dataset", blueprints.size, annualRows, quarterlyRows, true, "Synthetic sample entities")
        return blueprints.size to annualRows
    }

    fun quarterLabel(fyEnd: Int, quarter: Int): String = when (quarter) {
        1 -> "Jun ${fyEnd - 1}"
        2 -> "Sep ${fyEnd - 1}"
        3 -> "Dec ${fyEnd - 1}"
        else -> "Mar $fyEnd"
    }
}
